import{_ as t,o as a,c as i,a0 as n}from"./chunks/framework.veCcaNqE.js";const h=JSON.parse('{"title":"Linear Functions in Quadratic Models","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quadratic-functional/linear-compositions.md","filePath":"guide/quadratic-functional/linear-compositions.md"}'),o={name:"guide/quadratic-functional/linear-compositions.md"};function r(s,e,d,c,u,l){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="linear-functions-in-quadratic-models" tabindex="-1">Linear Functions in Quadratic Models <a class="header-anchor" href="#linear-functions-in-quadratic-models" aria-label="Permalink to &quot;Linear Functions in Quadratic Models&quot;">​</a></h1><p>Linear and quadratic model functions serve different purposes. A linear-input function can often be reused in a quadratic model because its generated rows remain linear. Functions that accept a quadratic polynomial compose the same operation over a nonlinear input and may add quadratic equalities.</p><h2 id="reusing-linear-input-functions" tabindex="-1">Reusing linear-input functions <a class="header-anchor" href="#reusing-linear-input-functions" aria-label="Permalink to &quot;Reusing linear-input functions&quot;">​</a></h2><p>Linear expressions are valid components of quadratic objectives and constraints. Existing linear functions such as <code>MinFunction</code>, <code>MaxFunction</code>, <code>AbsFunction</code>, <code>MaskingFunction</code>, <code>IfFunction</code>, and the exact composite functions can be reused when their inputs are linear and their generated formulation is linear. Their ordinary MILP exactness and finite-bound requirements continue to apply. This includes <a href="./../linear-functional/composite-cardinality.html">cardinality, positive-part, clamp, complementarity, and distance functions</a>, <a href="./../linear-functional/order-statistics.html">order statistics</a>, and <a href="./../linear-functional/risk-global-constraints.html">CVaR</a>. In Rust, build expressions that use helper variables from the registered solver-index map exposed by the owning symbol.</p><p><code>ProductFunction</code> multiplies two linear expressions and returns a quadratic expression. It does not introduce a result variable or a linearization. A solver that accepts quadratic expressions is required.</p><p><code>QuadraticLinearFunction</code> binds a quadratic expression to a signed real helper variable through an equality, so the value can be reused in linear-input function interfaces. That equality is quadratic; the resulting model is MIQCP and may be nonconvex.</p><h2 id="composing-functions-over-quadratic-inputs" tabindex="-1">Composing functions over quadratic inputs <a class="header-anchor" href="#composing-functions-over-quadratic-inputs" aria-label="Permalink to &quot;Composing functions over quadratic inputs&quot;">​</a></h2><p>Quadratic counterparts such as <code>QuadraticAbsFunction</code>, <code>QuadraticMaxFunction</code>, <code>QuadraticMinMaxFunction</code>, <code>QuadraticMaskingFunction</code>, and <code>QuadraticIfFunction</code> apply familiar function semantics to quadratic input polynomials. Each genuinely quadratic input is represented by a signed bridge variable and an exact quadratic equality. Affine inputs need no bridge. The function&#39;s other linearization rows are then formed over the bridge value.</p><p>This avoids expanding products of quadratic expressions into cubic or quartic terms. It does not make the model linear: expect MIQCP constraints and use a solver that supports the required quadratic constraints. Convexity and performance depend on the whole model.</p><h2 id="model-guarantees" tabindex="-1">Model guarantees <a class="header-anchor" href="#model-guarantees" aria-label="Permalink to &quot;Model guarantees&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Construction</th><th>Guarantee</th><th>Solver/model class</th></tr></thead><tbody><tr><td>Bounded integer product or exact selector</td><td>Exact for all objective directions</td><td>MILP</td></tr><tr><td>McCormick envelope for continuous factors</td><td>Convex-hull relaxation over the declared box</td><td>LP/MILP relaxation</td></tr><tr><td>Nonlinear piecewise function</td><td>Linear interpolation of supplied points; no automatic error bound</td><td>MILP with segment selectors</td></tr><tr><td>CVaR exact candidate enumeration</td><td>Exact for all objective directions</td><td>MILP</td></tr><tr><td>CVaR epigraph</td><td>Tight at an optimum when minimized; a result upper bound projects exactly to <code>CVaR &lt;= limit</code> but does not force equality</td><td>LP/MILP epigraph</td></tr><tr><td>Quadratic bridge equality</td><td>Exact equality to quadratic input</td><td>MIQCP, possibly nonconvex</td></tr></tbody></table><p>The correct choice depends on the semantics needed. A relaxation may be useful in a bound or decomposition but should not be described as an exact product. A PWL model approximates the source curve. A CVaR epigraph becomes tight when its expression is minimized; a result upper bound preserves the exact risk-feasibility test without fixing the auxiliary expression to CVaR. A quadratic bridge preserves an equality but changes the solver class.</p><p>See <a href="./product.html">product expressions</a>, <a href="./quadratic-abs.html">quadratic input functions</a>, and the linear-model pages for <a href="./../linear-functional/composite-cardinality.html">composite, cardinality, and distance functions</a>, <a href="./../linear-functional/order-statistics.html">order statistics</a>, <a href="./../linear-functional/slack-range.html">slack ranges</a>, <a href="./../linear-functional/products-selection.html">products and selection</a>, <a href="./../linear-functional/nonlinear-tariffs.html">nonlinear approximations and tariffs</a>, and <a href="./../linear-functional/risk-global-constraints.html">risk measures and global constraints</a>.</p>',13)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
